#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (8) ---
patchFile('siman_019/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The laws of the blessing on shechita. In it are 8 seifim. One who slaughters must bless before [reciting] "asher kidshanu bemitzvotav vetzivanu" on the shechita; and if he slaughtered and did not bless, it is kosher. {Rama: And if he slaughtered something in which a defect may develop and examination is required, he should slaughter it without a blessing; and when it is found kosher he blesses on the shechita, provided that he is close to the shechita, and he should not speak until after the shechita. (Or Zaru'a, laws of kisuy hadam, not like Rashi in a responsum.) And if he slaughtered in a kitchen, which is a foul place, he should bless at a distance of four amot before he enters there, and he should not speak until after the shechita (old Hagahot Shechitot in the name of the Agudah).}`,
  '2#main': `If he slaughtered animals, beasts, and birds, [he recites] one blessing for all of them.`,
  '3#main': `[When] two people are slaughtering two animals, one may bless to discharge his fellow, provided that he intends to discharge him.`,
  '4#main': `He must take care not to speak between the blessing and the shechita about a matter that is not required for the shechita; and if he spoke, he must bless again. (But it is permitted to speak between the shechita and the covering [of the blood].) (Mordekhai, chapter 25, in the name of Sefer HaTerumah.) (Nevertheless, it is good not to speak.) (Terumat HaDeshen, Ashrei, siman 46, and R' Yerucham and the Agudah):`,
  '5#main': `If he wishes to slaughter many [animals], he must take care not to speak between one shechita and another about a matter that is not required for the shechita; and if he spoke, he must cover the blood of the first shechita and bless again on the shechita, but he does not bless on the second covering. {Rama: Because the shechita is not an interruption; but if he spoke in between, it is an interruption and he must return and bless (Kol Bo, Ashrei, and all the poskim).} And some say that speech between one shechita and another is not an interruption.`,
  '6#main': `One who blesses with the intention of slaughtering one animal and afterward they brought him more—he covers the blood of the first and blesses on it, and blesses on the second shechita but not on the covering; and this applies when they brought them to him before he blessed on covering the first. (The Beit Yosef's opinion, and Rashal, siman 205, seif 8:) {Rama: And some say that if they brought him of the same species that he slaughtered first, he need not cover the first and bless on the second shechita (Tur in the name of Ba'al HaItur) (and such is the essential ruling; see in Orach Chaim siman 206, seif 1):}`,
  '7#main': `If many [animals] were before him to slaughter and he blessed on the shechita and afterward they brought him more—if when they bring him the later ones there are still before him some of those that were before him when he blessed, he need not return and bless; and if not, he must bless. And l'chatchila it is good to take care that his intention at the time of the blessing be on all that they will bring him.`,
  '8#main': `If he was slaughtering an animal or bird and his intention was to slaughter more and he forgot and covered [the blood] and blessed—when he returns to slaughter he need not return and bless on the shechita, for the covering is not an interruption. {Rama: And the same law applies if he slaughtered a chaya (or bird) and wishes to slaughter a behama—he covers the blood of the chaya and slaughters the behama without a blessing (Kol Bo):}`,
});

// --- siftei-kohen (13) ---
patchFile('siman_019/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `Kosher. Even if he acted deliberately and did not bless, it is kosher—even for himself; and so wrote the Beit Yosef, and Darkei Moshe, and Maharshal in the chapter on kisuy hadam, seif 1; and so it appears in the BeHag at the beginning of daf 126; and the Bach did not rule thus—and see below siman 28:`,
  '1#ב': `A matter in which a defect may develop, etc. And Maharshal there, siman 5, ruled like Rashi (and the Bach in this siman wrote on this Maharshal like the Or Zaru'a; in my humble opinion he did not examine carefully all Maharshal's words on this)—that he blesses before the shechita, for even if it becomes treifah the shechita avails for it to be purified from nevelah status; and it does not appear so in the Yerushalmi in the chapter "HaRo'eh," in what they say there regarding the blessing on shechita: the presumption is that the intestines are kosher—and see below siman 28, seif kaf vav:`,
  '1#ג': `And when it is found kosher he blesses, etc. And in Darkei Moshe he brings in the name of the Hagahah of Ashrei on the first chapter of Chullin that even on a kosher animal, if he forgot and did not bless before the shechita, he should bless after the shechita, end of his words; and so it is found in Miktzat Shechitat HaAchronim, and in the Hagahah of Ashrei there he concludes that every mitzvah on which he did not bless—he transgresses its performance, and he blesses after doing it, as the Avnei Nezer explained in Berachot from the Or Zaru'a, end of his words. But in the first chapter of Berachot they wrote as follows: where one did not bless before the mitzvah, he blesses after the mitzvah and fulfills his obligation; however, regarding a meal, where it is forbidden for a person to benefit without a blessing, once he transgressed and ate and the time for Birkat HaMazon arrived, since it was pushed aside it was pushed aside—or so the Or Zaru'a (end of his words). However, this is not the Rambam's view—in chapter 11 of Hilchot Berachot, law 6, he wrote that if one slaughtered without a blessing, even if he separated terumot and maasrot or immersed and did not bless, he does not return and bless after the deed; and so for all similar cases, end of his words. And in Sefer Berachat Avraham, end of part 1 and beginning of part 10, he greatly extended to refute the Rambam's words with rhetoric, and his main foundation is that if it were so that one does not bless after doing them, then where do we permit a convert (as below siman 268 seif 2) and similarly other those obligated in immersion (as below siman 120) and other mitzvot—to bless l'chatchila after doing them; and if because he could not bless beforehand the blessing would not apply at all, end of his words—and all his words do not appear correct to me, for we certainly hold that all berachot are d'rabbanan except Birkat HaMazon, as stated in Berachot in several places and among the poskim; if so, they said to bless before the mitzvah and not after the mitzvah at all, and they said regarding a convert and similar cases that while the person is still not fit he blesses after the mitzvah—and so it appears in chapter 3 "that they ate" (daf 51a) where they say there that Ravina said: therefore even if he finished eating he should return and bless, as it is taught: one who immersed and ascended says upon his ascent, "Blessed are You, Lord our God, King of the universe, Who has sanctified us with His commandments and commanded us concerning immersion"—but that is not so, for there initially the person was not fit, here initially he was fit, and since it was pushed aside it was pushed aside; therefore it is only regarding immersion and similar cases because initially he was not fit, but where he was fit initially and did not bless, he does not bless afterward, and even though in Sefer Berachat Avraham he wrote that this applies also to shechita and similar, that is not so, for there it is Berachat HaMitzvot, etc., but it is preferable from it, etc.; however this is not required at all, and so R' Yonah in chapter 3 "that they ate" there—that the same applies to all other berachot that are said before doing the mitzvah: if he did not bless he does not bless afterward, see there (and further clear proof: they taught in the first chapter of Pesachim (daf 6b) that in the house of Rav they say: all berachot one blesses before doing them except immersion, for the person is still not fit; it is also taught thus: one who immersed and ascended says upon his ascent, "Blessed... upon immersion"; and if it were so, what proof do we bring from this baraita—perhaps only one who immersed and ascended, but not l'chatchila; and like Ravina who explains it as b'dieved only, for regarding other mitzvot too if he did not bless initially he blesses afterward; rather certainly the Gemara holds that if we do not say "the person is still not fit" and permit l'chatchila, then even b'dieved he does not bless, since it was pushed aside; and so it appears explicitly from the words of the Tosafot in the chapter "Lulav HaGazul" (Sukkah daf 39a) and the Rosh there, who wrote that if he took the lulav in his hand without a blessing, it must be that he blesses afterward, since the mitzvah is not yet fully completed, for it requires shaking, end of his words—it appears that if he completed the entire mitzvah, and so generally where this reason does not apply, he does not bless (in Nekudat Kesef they delete from "and further proof" until here; and some emend there "if so, even b'dieved he does not bless, since it was pushed aside," and examine this). And also in Piskei Rekanati siman 72 he brought the words of the Or Zaru'a and afterward the words of the Rambam in the conclusion—it appears that he holds thus; and so wrote Rabbeinu Avudraham in the name of Ba'al HaMaor like the Rambam; and so it appears from the words of the Rif in a responsum regarding the blessing on milah that R' Moshe Alshakar brought in his responsum siman 18; and further, we hold that every safek in berachot we are lenient:`,
  '1#ד': `He blesses, etc. The Ittur wrote that we are accustomed that when it happens that one will slaughter something that has a safek of treifah, he slaughters a chicken or another bird before it—and his intention is also about this; and so wrote the Bach; and this is a correct matter; and so it is below siman 28 regarding kisuy haba al yad terefah; nevertheless the law of the Rambam is true where it is not possible to slaughter another bird—and examine this.`,
  '3#_': `And provided that he intends to discharge him. And his fellow must also intend to be discharged—Tur; and see in Orach Chaim siman 213 and Tikkun 85.`,
  '5#א': `He must cover the blood of the first shechita, etc.—for since he spoke about other matters that are not required for the shechita and must return and bless on the second shechita, he must complete the mitzvah of the first shechita; therefore he covers and blesses again on the second shechita, but on the second covering he does not bless, since at the time he blessed on the first covering his intention was to slaughter and cover more; and the shechita is not an interruption, for it is possible to slaughter with one hand and cover with one hand; and the blessing on shechita is also not an interruption, as we find in Yoma—so too all the poskim.`,
  '5#ב': `And some say that speech, etc.—and the agreement of the poskim is that it is an interruption and he must return and bless; and so too Maharshal there siman 9, and so wrote Darkei Moshe, and so in Sefer Lechem, and the Ittur, and all the acharonim.`,
  '6#א': `He covers the blood of the first, etc.—because he changed his mind and his intention was not initially on them; and his law is like one who spoke, in seif kaf vav—so too all the poskim; and see in Orach Chaim siman 169 and 179.`,
  '6#ב': `And some say that if they brought him, etc.—and in the Ittur he concludes thus, and such is the essential ruling; and see in Orach Chaim siman 206; and so it is in some editions in the words of the Rambam, and so wrote Darkei Moshe that the Taz in Orach Chaim siman 206 ruled without qualification like Ba'al HaItur and not like the words of the Rosh, therefore; and in the Derishah he wrote as follows: and you may say—according to what they compared the blessing on shechita to the blessing on fruits, if so, when they brought him another species too, as the Beit Yosef wrote in siman 206, and so in the Shulchan Aruch there (and so it appears from the words of the Rambam there, and so ruled the Levush there); and further, according to this it is difficult—the words of the Tur who wrote nearby that even if some of that species on which he blessed are still before him and they brought him more of that species, he must return and bless on what was brought; and this is against what is written in siman 206; rather it must be as the Beit Yosef wrote, that there is a distinction between eating, which has a fixed measure, and shechita, which has no fixed measure, etc.; and so in Sefer Lechem; and he wrote that so it appears explicitly from the words of the Rosh, like the Tur's view and not like Ba'al HaItur; and he ruled thus, see there; and so it appears explicitly from the words of all in Kol Bo; and so the implication of the poskim; and so it appears from the words of Maharshal there; and so Rabbenu Yerucham, Netiv 1 end of part 2—that when one circumcised one infant and his intention was not initially on the second, he must bless on the second; and the Rambam himself brought this in siman 265 seif 5; and so the Ittur there; and it is explained there in Rabbenu Yerucham that the law of milah and shechita is the same in this; and so in Avudraham, laws of milah, and in Mordekhai at the end of the chapter on kisuy hadam, see there.`,
  '7#א': `Many were before him, etc.—and the same applies if one was before him and after he blessed, before he slaughtered, they brought others before him—he need not return and bless; and so it is proven in the Beit Yosef.`,
  '7#ב': `And l'chatchila, etc.—because the Tur holds that always whatever was not before him when he blessed requires a blessing unless his intention was on all that they will bring him; therefore, to remove himself from the dispute and to rule like all, he should l'chatchila set his intention on all that they will bring him; and similarly wrote the Rambam in Orach Chaim siman 206; and Maharshal, Perishah, and the Bach wrote that a hired slaughterer designated to slaughter permanently in a place—his intention is always on all that they bring him, even of two species, and he need not bless as long as he did not slaughter in the meantime.`,
  '8#א': `And he forgot and covered, etc.—and regarding the second covering see what the Ittur wrote, for they are words of reasoning.`,
  '8#ב': `He covers the blood of the chaya, etc.—and according to what we hold below siman 28 seif 20 that one must examine the lung before covering, if so he will interrupt greatly between one shechita and another and will need to bless again; in my humble opinion he should slaughter the behama first and afterward cover the chaya; and it is possible to say regarding slaughtering between one chaya and another when he changed his mind—that he must cover the first chaya first, for there it is different since he must return and bless; and so it appears in Ashrei and the poskim; not so here—and all this is possible if he does not hold the law below siman 28, or it is possible he did not descend to these laws and came only to teach us that covering is not an interruption, and we learn from it regarding a bird that he mentioned there too; and so it appears from his words there—and examine this.`,
});

// --- turei-zahav (17) ---
patchFile('siman_019/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#א': `And he did not bless—his shechita is kosher; to exclude the laws of Eldad HaDani that the Mordekhai brought, who forbade the shechita in this case; and the Mordekhai wrote in the chapter on kisuy hadam in the name of Rabbenu Yitzchak bar Avraham that nevertheless, if he did so deliberately it is forbidden to eat from it and they would strike him, but after [the fact] it is permitted; and the Beit Yosef wrote that the Rambam and other poskim disagree with Rabbenu Yitzchak bar Avraham; and the Maharach wrote that nevertheless one should be stringent to penalize him like Rabbenu Yitzchak bar Avraham.`,
  '1#ב': `He should slaughter it without a blessing. And some are accustomed to slaughter with it a kosher shechita—and this is preferable.`,
  '3#_': `One may bless, etc.—it teaches us here that it is not only regarding Birkat HaNehenin, where they all have one fixed [measure] so one blesses for all, as written in Orach Chaim siman 213; not so here, where each one slaughters a different animal—there is no [rule that] one discharges his fellow; it teaches us as stated.`,
  '4#א': `Between the blessing and the shechita. This is simple in everything that requires a blessing.`,
  '4#ב': `Between the shechita and the covering. For he holds that covering is a mitzvah in its own right; but some say that covering completes the shechita; therefore the Rambam wrote that it is good to take care not to speak, since he is in the middle of the mitzvah; even though if he spoke he need not bless again—even within the shechita itself—nevertheless l'chatchila it is proper to be careful in this.`,
  '5#א': `And if he spoke he must, etc.—for he holds that between one shechita and another it is like [one who] spoke between [putting on] tefillin and tefillin, where he must return and bless; therefore he must complete the first shechita and cover its blood; and there is a printing error—it should say: he must cover the blood of the first shechita and bless on it, and bless again, etc.`,
  '5#ב': `Because the shechita is not an interruption. Explanation: between the coverings—for his intention was on the second covering at the time he blessed on the first, and there is no interruption here, for it is possible to slaughter with one hand and cover with one hand; and the blessing on the second shechita is also not an interruption, since he did not speak idle words of Chullin as we find in Yoma.`,
  '5#ג': `To return and bless. Explanation: on the second covering, as with an interruption between slaughterings.`,
  '5#ד': `And some say that speech, etc.—he holds that it is different between tefillin and tefillin, for there are two obligatory mitzvot, and since he began them it is not proper that he interrupt and occupy himself with speech; but here, if he wishes he slaughters and if he wishes he does not slaughter—he is not obligated to return and bless, and it is like speaking in the middle of a meal; therefore he need not cover the blood of the first at all, but he slaughters more and covers everything at once; and since the Shulchan Aruch did not decide, we hold like those who say that a safek in berachot is lenient; therefore one must take care not to speak between one shechita and another so as not to bring himself to a safek.`,
  '6#א': `He covers the blood of the first. For he changed his mind—and there was an interruption between the first blessing on the shechita; and his law is like one who spoke idle words of Chullin, in the first view in seif 5; and they learned this from the attendant who must bless on each slice at a meal: they challenged him—what is different from "give us and we will bless" and he wishes to eat more, that he must bless HaMotzi, but he need not bless Birkat HaMazon on what he already ate? For there it is different, for Birkat HaMazon is praise to the Holy One, blessed be He, for man's enjoyment, and one acknowledgment suffices for two eatings; but the act of covering completes the shechita and he must complete it before beginning the other—so too the Rosh.`,
  '6#ב': `Of the first species. This is Ba'al HaItur's view in the Tur; and it appears he compared it to fruits, as written in Orach Chaim siman 206: he blessed on fruits before him and afterward they brought him more of that species—he need not bless, even if they were not before him when he blessed, end of his words; and from here it is difficult for what the Beit Yosef wrote—that it is not specifically of that species literally, but we mean that it should be of the type of the first blessing, end of his words; but here Ba'al HaItur distinguishes between chaya and bird, and their blessings are the same, and nevertheless he must return and bless; and the Tur concludes here, and the Rosh did not distinguish—meaning, even if they brought him of the first species he must return and bless; and it appears he holds it is not similar to fruits we mentioned, for in eating a person's nature is to continue and add more, and therefore it is as if they were before him at the time of the blessing; not so with shechita; and the Beit Yosef wrote that the Ran in the name of R' Meshulam, the Raavad, and the Rambam hold like the Rosh; if so, Ba'al HaItur is alone against them.`,
  '7#א': `They brought him more. Explanation: of another species—according to Ba'al HaItur nearby; and for the Rosh and other poskim, even of the same species.`,
  '7#ב': `He need not return and bless. This is the Semag's view; and the Beit Yosef gave a reason: whatever is still before him, he is fixed to slaughter; but when he finished it is a departure and comparable to what we say: one who finished eating is forbidden to eat until he blesses; and even though we do not hold so there, a meal is different, for it is usual to continue from eating to eating; but regarding shechita, when he finished it is a complete departure; and the Tur disagrees on this and holds that what remained before him from the first ones does not avail, since at the time of the blessing they were not before him; and the Beit Yosef decided like the Semag.`,
  '7#ג': `And l'chatchila it is good, etc. Rashal wrote: and for a city slaughterer, always consider his intention to be on others; and whenever they bring before him and he did not slaughter in the meantime, he need not return and bless, end of his words—it appears even of two species.`,
  '8#א': `To slaughter more and he forgot and covered, etc.—thus it should read.`,
  '8#ב': `He need not return and bless on the shechita. And regarding the blessing on covering he did not mention anything, as he mentioned above regarding the law of interruption through speech or through changing his mind—that one need not return and bless on the covering; for there his intention at the time of the blessing on covering was on what he would cover afterward, for he knew he would return and slaughter; but here he forgot and thought he would not slaughter more—certainly he must bless afterward on the second covering, which is a new mitzvah that came to him, as stated.`,
  '8#ג': `And the same law if he slaughtered a chaya, etc. This deals with one who at the time of the blessing on shechita also intended on slaughtering the behama, or the behama was before him at the time of slaughtering the chaya—according to the Semag nearby; therefore he need not bless on slaughtering the behama; rather it teaches us that he covers the blood of the chaya first before slaughtering the behama.`,
});

// --- baer-heitev (12) ---
patchFile('siman_019/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#א': `Kosher. And the Bach wrote that one should penalize him not to eat from it himself; but for others it is permitted. Ben Paku'a that spread out on the ground and requires shechita from doubt—he blesses on the shechita (Peri Chadash); and he concludes in kaf alef that if there is no expert there for examination, it is permitted to make it nevelah without a blessing; but if there is one expert there for examination, he must slaughter and examine, even if his intention is only to feed gentiles, for it is fit for him.`,
  '1#ב': `On the shechita. And the Taz wrote: and some are accustomed to slaughter with it a kosher shechita, and this is preferable.`,
  '1#ג': `On the shechita. And the Shach wrote: some wish to say that even on a kosher behama, if he forgot and did not bless before shechita, he blesses after shechita; but the Shach disagrees on this and wrote: wherever one must bless and did not bless initially, he has no remedy; and the Peri Chadash wrote that within the time of speech after shechita he can bless; if he is obligated to slaughter for a gentile and is not expert in laws of shechita, he is not permitted to bless, since he will not end up eating from it—see responsa Sha'ar Efrayim siman 57; and if he spoke he need not bless again, even if he spoke within the shechita itself; nevertheless l'chatchila he must be careful (Maharam Tiktin).`,
  '3#_': `To discharge him. It teaches us here that it is not only regarding Birkat HaNehenin, where they all have one fixed [measure], so one blesses for all, as written in Orach Chaim siman 213; not so here, where each slaughters a different animal—there is no [rule that] one discharges his fellow; it teaches us.`,
  '4#_': `To speak. And the reason is because covering completes the shechita.`,
  '5#א': `Interruption. And the reason is in the Taz: for his intention was on the second covering at the time he blessed on the first, and there is no interruption here, for it is possible to slaughter with one hand and cover with one hand; and the blessing on the second shechita is not an interruption, as in Yoma, end of his words; and the Taz ruled that since the Shulchan Aruch did not decide, we hold that a safek in berachot is lenient; the Peri Chadash wrote to warn slaughterers to avoid safek berachah—that they should finish in their minds and intend not to be discharged with the first blessing only as long as they do not speak idle speech; for now if he interrupted with speech, the first blessing does not avail.`,
  '5#ב': `Interruption. And the Shach wrote that all the latter poskim ruled that it is an interruption; therefore it appears one should not speak so as not to come to a safek.`,
  '6#_': `Second. And the Taz and Shach wrote that it appears from here that he compared the blessing on shechita to fruits—in Orach Chaim siman 207 he wrote there: he blessed on fruits of the land and afterward they brought him more of that species—he need not bless. (They also wrote there in the name of all the acharonim who ruled like the Rosh that even if they brought him of the first species he must return and bless.) And from here it is difficult for what the Beit Yosef wrote there—that it is not specifically of that species, but that it should be the blessing of that type; but here Ba'al HaItur distinguishes between chaya and bird, and their blessings are equal; and it must be that he does not compare it to fruits, for in eating a person's nature is to continue and add more, and therefore it is as one who was before him at the time of blessing; not so with shechita, end of his words.`,
  '7#א': `To slaughter. And the Shach wrote: the same applies if one was before him to slaughter and after he blessed, before he slaughtered, they brought more before him.`,
  '7#ב': `For him. The Shach wrote that a permanent slaughterer—certainly his intention is on all they bring him, even of two species, and he need not bless as long as he did not slaughter in the meantime (Rashal and Bach). And if he has many birds to slaughter and blessed at the beginning of slaughter and another comes to take from those birds to slaughter— that other must bless (Hilkhot Ketanot siman 115).`,
  '8#א': `Interruption. And the Taz wrote: but on the covering he is obligated to bless, because he forgot and thought he would not slaughter more; and that which in seif 5 regarding interruption through speech one need not bless again on the covering—there his intention was initially at the time of the blessing on covering on what he would cover afterward, for he knew he would slaughter afterward (Maharam Tiktin).`,
  '8#ב': `Blessing. And the Shach wrote: but according to what we hold below siman 28 seif 20 that one must examine the lung before covering—if so he will interrupt greatly between one shechita and another and will need to bless again; in my humble opinion he should slaughter the behama first and afterward cover the chaya.`,
});

// --- beer-hagolah (8) ---
patchFile('siman_019/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Rambam, chapter 1 of Hilchot Shechitah; and the Rosh and Mordekhai at the beginning of Chullin`,
  '2#_': `The statement of Rabbi Chanina—even according to Rabbi Yehudah, Chullin daf 86`,
  '3#_': `The Rosh there, from the Tosefta`,
  '4#_': `Tur—from that which is in Berachot daf 40: forming the dough is an interruption; this matter is a different interruption`,
  '5#_': `Tur—from the words of the Tosafot, Chullin daf 87`,
  '6#_': `There—and the Rashba and the Ran in the name of the BeHag and the Raavad; and so too the Semag; nevertheless one must take care not to bring himself to another blessing, since he can discharge himself with the first blessing—Tosafot, Rosh, Rashba, and Ran in the chapter mentioned`,
  '7#_': `There—in the name of the Ramban and R' Yonah`,
  '8#_': `Tosafot and the Rosh there, and Shulchan Aruch from that which we hold like Ameimar regarding one who changed his mind, Pesachim daf 102`,
});

// --- beur-hagra (20) ---
patchFile('siman_019/beur-hagra/part-001.txt', 'beur-hagra', {
  '1#א': `One who slaughters, etc. Gemara, first chapter of Pesachim 7b; and Yerushalmi, chapter 9 of Berachot: one who slaughters must say "Blessed are You... upon the shechita."`,
  '1#ב': `Before. Gemara there and Yerushalmi there, and like Rabbi Yochanan, and as written below.`,
  '1#ג': `And if he slaughtered, etc. Tosafot on Zevachim 31b, s.v. shehashechitah, etc.; and Rosh and Shulchan Aruch; and in chapter 2 of Berachot (15a)—and not regarding a berachah, etc. (Likut) And if, etc.—chapter 1 of Terumot, five, etc.; and Ittur there (end of his words).`,
  '1#ד': `And if he slaughtered, etc. Yerushalmi there: when does one bless on it? Rabbi Yochanan said: before the shechita; Yossi ben Nehorai said: after he slaughters—lest the shechita become invalid from now; one examines—the presumption is that the intestines are kosher; it appears that there is a defect, but according to all, after examination where there is no defect we hold like Rabbi Yochanan, and as written in Pesachim there that we are not concerned lest the shechita be ruined.`,
  '1#ה': `At a distance of four amot. Meaning: behind him, as written in chapter 3 of Berachot (22b, 25a, 26a).`,
  '1#ו': `And he should not speak. As written at the beginning of chapter 6 there, 40a.`,
  '3#_': `And provided that he intends, etc. End of chapter 3 of Rosh HaShanah.`,
  '4#א': `He must, etc., about a matter, etc. BeHag, seif kaf dalet; and Tosafot there.`,
  '4#ב': `But it is permitted, etc. Ittur; and Orach Chaim siman 498, seif 8; and for evening, etc. (and below siman 28, seif 3 and 15).`,
  '5#א': `He must take care, etc. Because of a berachah that is not needed, as written in Yoma 70a and in Sotah 41a. (Likut) If he wishes, etc.—because of a berachah that is not needed, as written in Yoma 70a; old Tosafot there, s.v. mishum, etc.—from here one may learn, etc.; and Tosafot on Chullin 87a, s.v. umichsei, etc. (end of his words).`,
  '5#ב': `And if he spoke, etc. As written in chapter 3 of Menachot (36a) regarding tefillin.`,
  '5#ג': `He must cover. As written there—Rabbi Yehudah in the mishnah, chapter 6, 2b; and even though we do not hold like Rabbi Yehudah, because one berachah suffices, as written in the Gemara there; and Tosafot, s.v. umichsei.`,
  '5#ד': `But on, etc., because, etc. As stated—Rabbi Yehudah concedes, etc.; here it is possible to slaughter, etc.; and the same here; and this is what is meant by "but if," etc.; and as stated regarding shechita.`,
  '5#ה': `And some say, etc. For it is not similar to tefillin—for there are two obligatory mitzvot; but here, if he wishes he slaughters and if he wishes he does not—it is like speaking in the middle of a meal.`,
  '6#א': `One who blesses, etc. BeHag; and in Chullin there he compares to the students of Rav; and in Pesachim there—Ameimar holds like the students of Rav.`,
  '6#ב': `He covers, etc. As stated in the previous seif.`,
  '6#ג': `And this applies, etc. As stated—because he changed his mind.`,
  '6#ד': `And some say, etc. As written in the Beit Yosef in Orach Chaim siman 206 and Shulchan Aruch there; and he learned from what is written (Berachot 41b) regarding matters that come because of a meal—that Birkat HaMotzi discharges them; and the Rashba wrote: even if they were not at the time of Birkat HaMotzi; and so is the plain meaning of the sugya there and at the end of chapter 7—they are all dependent on the berachah; except that the Beit Yosef and Shulchan Aruch wrote there that even if it is not of the first species, only that their berachot are equal; if so, here one need not [require] of the first species; and see the words of the acharonim here and there.`,
  '7#א': `If many, etc., and if they brought him, etc. As written in chapter 6 of Berachot (42a): one who ascends is forbidden to eat; and even though we do not hold so—a meal is different, for it is usual to continue from eating to eating.`,
  '7#ב': `And l'chatchila, etc. For then according to all he need not bless in any case, as written in Orach Chaim, end of siman 206, regarding "emet mayim" from the Yerushalmi.`,
});

// --- kereti (13) ---
patchFile('siman_019/kereti/part-001.txt', 'kereti', {
  '1#א': `And if he slaughtered and did not bless—the same applies if he did not bless deliberately; it is kosher even for the slaughterer himself—not like the Bach, who holds that his intention is to penalize the slaughterer and forbid the animal to him; and see Peleti.`,
  '1#ב': `Without a blessing—for perhaps it is treifah and there is no berachah here; and even though shechita purifies from nevelah status, nevertheless here the mitzvah of shechita does not apply, and shechita was not instituted for this; and all the more so the mitzvah and berachah—not like Maharshal and the acharonim.`,
  '1#ג': `And when it is found kosher—specifically in such a case he blesses afterward; but if he slaughtered and did not bless, he may not bless after shechita; such is the Rambam's view, and the Shach agreed with him, and the Peri Chadash—his view is like the Hagahah of the Rosh, who holds regarding berachot on mitzvot that if he did not bless before doing it he may bless afterward; and his words do not appear correct; and see Peleti. And behold the Peri Chadash's view: after completing the mitzvah, within twenty-four hours according to all he can bless, for it is like one who blesses at the time of doing the mitzvah; and see Peleti that I wrote his words do not appear correct, and he may not bless; and the rule is: safek in berachot is lenient because of concern for "lo tisa" (bearing God's name in vain), see there; and they wrote that now we are accustomed where there is a defect to slaughter first a bird or similar and bless and intend to discharge also this one in which a defect developed—and then there is no concern; and it is simple. And on Yom Tov, where one should not increase slaughter unnecessarily, one should act as the Rambam wrote.`,
  '1#ד': `That he be close to the shechita—meaning he should not divert his attention between the shechita and the berachah.`,
  '1#ה': `At a distance of four amot—I did not understand the need for four amot; immediately outside the kitchen he can bless; and see Peleti: only in kitchens, if it is a special place for slaughtering and there is filth, he may distance four amot and slaughter; but if the whole room is full of filth and he sells in it, he blesses outside the room—he need not distance four amot at all, only he can slaughter immediately; see Peleti. And that he can slaughter outside—this means there is no gap from there until the place of slaughter of twenty-two amot; and even if it is in two rooms, nevertheless it is not called an interruption, since his intention when he blesses is to slaughter inside; but if there is a distance of twenty-two amot it is an interruption and it is forbidden to slaughter relying on this blessing. So I raised in Peleti.`,
  '3#_': `One may bless one [blessing] and discharge his fellow—it appears that initially permission is given to do as he wishes; and so in Orach Chaim siman 8, seif 5, regarding tzitzit: either each for himself or one discharges his fellow; but in laws of milah siman 288 he wrote regarding two circumcisions for two infants—one blesses and discharges the second; and a reason is needed why this differs from that; and it is strained to say: since milah is done for many in assemblies and there is more "multitude with the glory of the king," like Beit Hillel's reason in the chapter "Elu Devarim" regarding a candle—that one blesses for all; not so in other matters where it is not usual to be in a multitude—they were not so concerned; and still requires further study.`,
  '4#_': `Between shechita and covering—for it is a mitzvah in its own right; and since many say it pertains to shechita, therefore the Rambam wrote that l'chatchila he should not speak.`,
  '5#א': `To slaughter many—see Peleti that I raised: if it becomes treifah there is a safek whether he must bless anew; therefore he should leave it for another slaughterer to slaughter, and then he can slaughter.`,
  '5#ב': `And if he spoke, etc.—it is an interruption; even though we hold regarding shofar that speaking between one tekiah and another is not an interruption—for there it is one mitzvah; here there are two mitzvot.`,
  '5#ג': `It is not an interruption—and the acharonim agreed it is an interruption, for they are two mitzvot, and it is like tefillin of the arm and of the head; and since it is a safek in berachot, if there is another slaughterer he should slaughter another and bless and intend to discharge him—and thus he exits the safek.`,
  '6#_': `And such is the essential ruling—its main place is in Orach Chaim siman 206, etc.; and there the Magen Avraham extended, and I too extended in my chiddushim—and so in many places.`,
  '7#_': `And l'chatchila, etc.—and the acharonim wrote that a permanent slaughterer is as if his intention is on all they bring him; and so it is customary among Jews that they slaughter korbanot and bring them to one another and the slaughterer does not bless; but even in this they act lightly, interrupting with speech and the like between one shechita and another—and it is fitting to protest.`,
  '8#_': `He covers—for covering is not called an interruption, even if he must examine the lung before covering; and if before him are behama and chaya, or behama and bird—he slaughters the behama first so as not to interrupt between one shechita and another in covering (Peri Chadash).`,
});

// --- peleti (6) ---
patchFile('siman_019/peleti/part-001.txt', 'peleti', {
  '1#א': `And he did not bless—the Bach's view: if he did not bless deliberately, the animal is forbidden to the slaughterer; and the acharonim disagree. And there is somewhat of a proof not like the Bach—for it teaches "one who slaughters on Shabbat—it is kosher," see there; it is similar to our case where it teaches—and if so, in what the Mechaber wrote it is permitted according to all; but the slaughterer certainly did not bless, for he is included among those who cut and bless, etc.; and in the Gemara the simple understanding is that it deals with deliberate action; and see in the chapter "Three who ate" in the Rosh and Tosafot; nevertheless it appears permitted in what the Mechaber wrote, even for the slaughterer—and examine this.`,
  '1#ב': `And if a defect developed in it—even though we hold regarding a trampled bird in which a defect developed that we slaughter on Yom Tov, why should we be concerned regarding a berachah? For shechita on Yom Tov is not more severe; perhaps he holds like those who say one must examine them—as we learned; but in truth it is forbidden; but according to what we hold in Orach Chaim that it is permitted—why be concerned regarding a berachah? And it must be: since he can bless afterward when it is found [kosher], we do not rely on the presumption; not so on Yom Tov where there is no other way.`,
  '1#ג': `He blesses—the Shach brought here Sefer Berachat Avraham, who decides like the Hagahah of the Rosh on berachot on mitzvot: if he did not bless before doing it he blesses afterward—not so Birkat HaNehenin; and he disputes the Rambam, who holds regarding shechita and similar that if he did not bless beforehand he does not bless afterward; and the Shach decided like the Rambam, with proof from that which we say in Berachot: Rabbi [X] forgot and ate and did not bless—he blesses afterward, as we learned: one who immersed and ascended blesses "asher kidshanu..."; and the Gemara rejects: there it is different because the person was not fit, etc.; and the proof is clear—why did it not say we do not compare Birkat HaNehenin to Birkat HaMitzvot? Rather in truth this is not the main point, only it depends on whether the person was fit. And the Peri Chadash wrote there is no proof at all—for if it would answer by distinguishing mitzvah and benefit, it would still be difficult why it cited specifically immersion and not all mitzvot that share one law; and so it appears: in other mitzvot, even though after doing one is obligated in a berachah, nevertheless l'chatchila the berachah is before doing—not so immersion, which requires the reason that the person was not fit, end of his words; and these words have no substance—for if Ravina did not know that in every immersion one does not bless before immersion, daily practice would prove otherwise, that they would immerse and bless afterward, women and men; and the language of the baraita is precise: it teaches "one who immersed and ascended blesses," and does not teach "one who immersed and did not bless should bless when he ascends, Blessed are You..."; and the main thing is missing—therefore the explanation "one who immersed and ascended" is because he could not bless beforehand; if so, Ravina, who does not hold a distinction between benefit and mitzvot, should be difficult to himself: why on benefit and mitzvot do we bless beforehand, but on immersion afterward? Rather certainly he knew the person was not fit, only he holds that if berachot are not by nature [said] after doing, what of it that he could not bless initially—he is discharged without a berachah; rather berachot are by nature also at the end, and the Gemara rejects: they said and they said—in every place berachah beforehand, and where impossible beforehand, afterward; and if so the Shach's proof stands; and also what does the Gemara need to answer a matter that is not true—for even a matter that is beforehand, nevertheless since it is a mitzvah he blesses after doing, and it should have answered: truly we distinguish mitzvah from benefit; and this "before immersion"—Ravina already knew. If so, also Ba'al Berachat Avraham's rejection that the Gemara should have answered is not so—for how can the Gemara give a stumbling block in its words that imply where "person not fit" does not apply one does not bless at the end, especially according to what Ravina knew this view of "person not fit" only he holds it is not worth changing the nature of berachot; if so why is he disputed with the answerers on this view, that amoraim would dispute a view and not explain that in all mitzvot the sages' nature was so? Or it is not so; and the Shach's words are clear and refined; and how much did the Peri Chadash toil at length to reject the Rambam's words and strengthen the Hagahah of the Rosh. And I omitted the words of Tosafot Pesachim daf 115, s.v. matkip, etc., who wrote: he holds a mitzvah requires kavanah—for if not, the above in the first dipping, if he blesses in the second dipping it is a berachah levatallah; and similarly they wrote afterward: and if kavanah is not required, it is obvious he should not bless in the second dipping, for even if he did not bless in the first dipping he exited, and if he blesses in the second dipping it is a berachah levatallah—and this is a berachah on a mitzvah as is known; if so what of it that he already fulfilled the mitzvah—nevertheless since he did not bless initially he may now bless; and what would be levatallah? The matter is clear that he who blesses after the act—it is a berachah levatallah; and truth guides his way; and so it appears from the Ran explicitly that if he exited in the first dipping he should not bless on eating maror—and this is clear like the Rambam's view; and such is the essential ruling: the Peri Chadash wrote that even for the Rambam, within the time of speech after the act he can bless—a matter obvious to him, for us it is very doubtful; for what will within twenty-four hours avail, since the act was already done and one may not bless afterward; and regarding a convert who immersed—the law should have been to bless before immersion, only it was impossible; therefore it was arranged that he bless immediately within twenty-four hours upon ascending. And this for the Rambam's view there is no distinction in this matter between mitzvah and benefit, as proven above from the Gemara; and also that which we hold one swallows liquids without a berachah—he swallows them and does not make a berachah, for he cannot spit out because it is repulsive, and afterward it is after the act—and it is difficult he should bless within twenty-four hours for swallowing; therefore this has no dawn and no essence.`,
  '1#ד': `At a distance of four amot—I did not understand the Rambam, who rules in Orach Chaim siman 83 that even a bathroom, if surrounded by partitions, one may read outside the bathroom and need not four amot; and even those who disagree there—see Magen Avraham there—that is a bathroom whose essence and designation is for defecation, and therefore the partitions are also like excrement; but a kitchen—is its essence for excrement? And what of it that filth is placed there, namely blood and discharge of the animal; but its essence is not for that until the partitions are nullified; therefore the partitions for kitchens—and it is obvious he can bless outside; and so in a bathhouse, where it is forbidden to bless inside but permitted outside—Agudah as stated in chapter 3 of Shabbat; and the Magen Avraham brought it in Orach Chaim siman 64: one who wishes to drink in a bathhouse blesses in the outer house—and did not mention four amot at all; therefore it is clear the Agudah's intent is not from the room where they slaughter to distance from the room four amot, but it deals with the room itself where they slaughter animals, where blood and discharge from the animals are—a foul place; this is called a kitchen, for here there is no house prepared for slaughter, but a place of filth—and he distances four amot from it. And see the Agudah's language in the first chapter of Chullin: "One who slaughters who must bless on shechita in a foul place, like a kitchen—he blesses outside the kitchen at a distance of four amot in a clean place," end of his words—behold it wrote outside the kitchen and did not write outside the kitchen-house; and also "in a clean place"; and if it is outside the kitchen-house it is obvious it is clean like all places; rather it is precise: outside the kitchen—simply the place where animals are slaughtered and filth is found—only distance four amot from there; therefore it wrote it should be clean so filth does not spread there; and "kitchen-house" at first that it taught is only as a general example, for there they slaughter; but the essence of the distance is the place where they slaughter—and this is clear.`,
  '1#ה': `Four amot beforehand, etc.—if in another room: from the Rambam's words it appears another room is not an interruption; and the Magen Avraham in Orach Chaim siman 166 brought the Agudah's words in Shabbat: one who wishes to drink in a bathhouse, where he cannot bless, blesses in the outer room in order to drink in the bathhouse—for it is like from corner to corner, end of his words—and the same applies here. And the Magen Avraham wondered there: it deals with Kiddush in the place of a meal, as it is written "and you shall call Shabbat a delight"—one may say if his intention is to eat there it is Kiddush in the place of a meal; but regarding interruption—what does it avail whether his intention is for that or not? In any case it is an interruption; and he was aided by the words of Tosafot explicitly who wrote so. And it appears to say that certainly Tosafot and the Rambam gave the measure of interruption as twenty-two amot walking; and proof from that which we say in Zevachim regarding that which we learned: an asham metzora does not have immediate semichah to shechita—and the Gemara challenged: according to the one who says partial entry is not called entry, let him put his hand in and perform semichah; and it answers: distance it to the north; and they stood to calculate—and he walks twenty-two amot: ten amot the priests' feet and ten amot Israel's feet; and they all challenged—the Magen Avraham and Chavat Yair—but rather what of "partial entry is called entry"? He cannot put his hand in adjacent at the side of the opening and bring in the asham and slaughter it immediately—for according to all the courtyard is called north; and they left it requiring further study. And the Agudah certainly holds that in two rooms in any case it is called interruption; only in one room it is not interruption except twenty-two amot. If so the Gemara's words are correct: if partial entry is called entry he cannot put his hand in at all, only perform semichah outside and bring in the animal—since it is in two rooms it is interruption; but if partial entry is not called entry and he can put his hand in, then everything is in another room—he holds it is not interruption; and the Gemara answers: distance it to the north, etc.—and it is twenty-two amot and interruption. And these are the Agudah's words—it deals where there are not twenty-two amot, only from room to room; therefore it is compared to Kiddush in the place of a meal: if his intention is to eat there it is like that place; also here—all interruption is because of room to room: if his intention was on that room it is as if he is in that room and there is no room by itself and no interruption; and if so for this that room interrupts it is like Kiddush in the place of a meal—if his intention is on that room it is like one room; and so regarding bathhouse and kitchen—for since his intention was on that room to drink and slaughter, it is not like another room but like that room, and there is no interruption since there are not twenty-two amot. And if it is still difficult regarding semichah—to perform semichah outside and slaughter inside, and his intention was on inside—then still there is no room to room and no interruption; one may say that since he cannot enter there, what of it that his intention is there—since he cannot enter and partitions separate, it is obvious it is from room to room. And here it is difficult to me from the Yerushalmi in tractate Shekalim chapter 3, as taught: an interpreter was with him so they would not say in his mouth "buyer of shekalim"; and it challenged: "and he shall fill his mouth with water"—Rabbi Tarfon: because of berachah; and they explained he must bless on raising the shekalim; and it is difficult to bless before entering the chamber of shekalim with intention to contribute there, and afterward fill his mouth with water and enter; and if so it appears proven that from room to room is interruption. And it is possible to say, as stated above, that in any case there must not be twenty-two amot of interruption; and the chamber where the shekalim were for contribution was very long, and it does not suffice that between the place of berachah and the place of contribution there be less than twenty-two amot—and it is interruption. In any case we learn from this that all the Rambam's words mean there is no distance of twenty-two amot, but if there is a distance of twenty-two amot it is interruption.`,
  '5#_': `If he wishes to slaughter. I have a safek: if he began to slaughter one and blessed on shechita and it became treifah—can he slaughter others without a berachah? In the Yerushalmi: he took a knife intending to bless and it fell from him—he must return and bless; if so, this too is similar—for it fell from him, for it became treifah; and in Orach Chaim siman 206, seif 6, the Mechaber ruled he must return and bless; and the Rambam emended: namely, that his intention was not to eat of that species; if so, here too if his intention was clearly to slaughter another behama he need not bless. But in siman 100 the Mechaber brought two views, see there and in the Magen Avraham—and if so it fell into dispute. But to me it appears it is not similar—for there the berachah was that he would eat the fruit; since the fruit is lost, his berachah and thought are in vain; but here the berachah was to fulfill the mitzvah of shechita, and since he slaughtered the animal according to law and custom, only it was treifah—the mitzvah of shechita was fulfilled, for so is the mitzvah to slaughter and not to be concerned lest treifah be found, for we establish the presumption of kashrut; if so he did the mitzvah, and even though it became treifah and lacks benefit, nevertheless the mitzvah did not move from its place, and he too blessed on the mitzvah and blessed correctly. And in my humble opinion the reasoning is correct; nevertheless it is difficult for me to rely on this; therefore if his intention was not clear to slaughter others and it became treifah, he should not slaughter others—for why bring himself into safek berachah? Only if there is another slaughterer there, leave it for him to slaughter a behama or bird and bless and intend to discharge him—and thus he can complete slaughtering the remaining animals without concern—and examine this. And behold, from all the Shulchan Aruch's words we learn: if he has many birds or chayot to cover, he blesses on the first covering and afterward covers and continues without berachah; and it is difficult—for in the Gemara Chullin 87 we say: if the mitzvah of covering was his and another came and covered, he must give him ten [coins]; and the Gemara asks: reward for mitzvah or reward for berachah? A practical difference for Beit HaMikdash, where there is only one mitzvah and four berachot; and it is difficult why it says a practical difference in another matter not related to the animal, and does not say here: if many chayot or birds were before him to cover and he blessed on one and covered, and before he came to cover the second another came and covered—if the reason is mitzvah he must pay for he stole the mitzvah; but if the reason is berachah he did not steal, for he was not blessing; and perhaps one may say: if initially his intention in the berachah was on all he would cover, if afterward he covers he does two mitzvot—mitzvah of covering and also berachah—even though he does not bless on it, nevertheless since initially his intention was on this covering, it is as if he blessed on this covering; simple explanation—and the first berachah ascends for all and he takes reward for berachah and covering; if so, when another comes and covers, he does two evils with him—covering and berachah that he takes—and there is no practical difference—and examine this.`,
});

// --- pitchei-teshuva (8) ---
patchFile('siman_019/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `And he did not bless—it is kosher. Ittur, seif kaf alef, on what he wrote in the name of the laws of the land of Israel; and see in responsa Noda BiYehudah, part Yoreh De'ah siman 2, who challenged from one who threw a knife and it went and slaughtered without intention to slaughter—and thus he did not bless; and many such cases; and he answered that the reason of the laws of the land of Israel who forbids the shechita is because he holds that since he acted deliberately and did not bless, he is like an apostate regarding that matter, etc., see there; and it is astonishing—for behold in the Rosh, first chapter of Chullin siman 1, he wrote as follows: similarly he wrote "forgot and did not bless," etc., see there—apparently it deals with unintentional action.`,
  '2#_': `Kosher. BeHag in the name of the Peri Chadash; but if there is, etc., even if his intention is not, etc.; and see in responsa Shevut Yaakov, part 2, siman 36, who wrote that if he is in a year when the 9th of Av falls on Shabbat and there is concern he will come to loss in a way that it is permitted to slaughter even though he is expert in examination—he should not bless; however, if he can fulfill from it for Shabbat or give from it to a sick person and similar—he should bless, see there.`,
  '3#_': `And when it is found kosher. Shach, seif kaf gimmel, who agreed with the Rambam; and see in Sha'agat Aryeh, laws of Berachot siman 26, who attacked the Shach; and see in responsa Tiferet Tzvi siman 3, who rejected his words and agreed with the Shach, see there; and see in responsum Chinuch Beit Yehudah siman 29.`,
  '4#_': `On the shechita. BeHag in the name of Sha'ar Efrayim; and see in responsum Chinuch Beit Yehudah siman 20 and in responsum Pri Tevuah siman 66.`,
  '5#_': `He should bless at a distance of four amot. See in Tashbetz, part 2, siman 43, that his view is not so—for one does not bless on a mitzvah unless it is prepared before him to do immediately; and if there is no concern lest the butcher change his mind and not slaughter, therefore it appears he must slaughter first and immediately after shechita go outside and bless the berachah in a pure place—for since they bless, it is fine; and so one should do for the blessing on covering. Nevertheless he did not decide this except for halachah and not for practice, see there. And see in Magen Avraham siman 166, seif kaf gimmel, who also disagreed with the Rambam for another reason—because the berachah must be specifically in its place, and even the final berachah must be specifically in its place—all the more so the first berachah; and in the Agudah there it deals where everything is in one house, see there. And see on this in responsa Tiferet Tzvi, part Yoreh De'ah siman 3, at length.`,
  '6#_': `One berachah for all of them. See in Sefer Yeshuot Yaakov in Orach Chaim siman 206, seif kaf gimmel.`,
  '7#_': `He must bless. See Kol Bo, seif kaf vav, regarding whether if he blessed on shechita and it became treifah he can afterward slaughter others without a berachah; and see in responsa Zichron Yitzchak siman 105 what he wrote on this.`,
  '8#_': `It is not an interruption. See in responsa Noda BiYehudah, part Orach Chaim siman 14.`,
});

// --- rabbi-akiva-eiger-yd (2) ---
patchFile('siman_019/rabbi-akiva-eiger-yd/part-001.txt', 'rabbi-akiva-eiger-yd', {
  '1#_': `(Siman 19, seif 1, in the hagahah) And when it is found kosher he blesses after the shechita. I am astonished at the conclusion of the Shach, seif kaf gimmel, to halachah that if he forgot and did not bless before shechita he does not bless afterward—one may say the same applies when a defect developed in it: he does not bless afterward, for it is not similar to immersion of a convert, where we say: since initially he was not fit, it was not pushed aside—for since in any case he was not fit to bless beforehand, when the sages instituted this berachah of immersion of converts initially, here it was instituted to bless afterward; but the berachah on shechita they fixed and instituted before doing it; only in this matter where a defect developed in it he may not bless from safek—one may say: since it was pushed aside it was pushed aside, and there is no distinction between pushed aside due to transgression and unintentionally or due to coercion. Apply this yourself to a baal keri, who does not bless beforehand: if he ate while his keri was still upon him, or slaughtered then and immersed for his keri—can we say he blesses afterward on what he ate or slaughtered, since initially he was not permitted to bless? Or it appears: since the foundation of berachot they instituted before doing them, only now there was something preventing him from blessing—he does not bless afterward. And the source of the Rambam's law is the Or Zaru'a; and the Or Zaru'a follows his method, for the Hagahah of Ashrei in his name, first chapter of Chullin, wrote: regarding all mitzvot, if he did not bless before doing them he blesses afterward; but for us, who hold like the Rambam, one may say that here too he does not bless afterward—and requires further study for practical law. And in the foundation of the dispute between the Rambam and the Hagahah of the Rosh mentioned above, the Peri Chadash wrote to prove like Ba'al Berachat Avraham from that which we say in the first chapter of Pesachim regarding lulav: from the time it was gathered he exited—behold he blesses afterward; and the Taz wrote on this: if so, the baraita itself is difficult—why did they not institute l'chatchila to bless before doing it like all mitzvot, since it is impossible to bless beforehand, as Tosafot wrote (Sukkah 39); if so, here the Rambam concedes it is like immersion of a convert that it is not pushed aside at all, see there. And it is seemingly astonishing—for still it is difficult how the baraita teaches: all berachot one blesses before doing them except immersion—why did it not also teach except lulav? And it is strained to say two baraitot dispute on this, that this tanna holds it is possible to bless beforehand. And in my humble opinion one may say: the baraita cited except immersion—for regarding this specifically [blessing is] after doing, and even b'dieved one does not fulfill if it was in his hand beforehand—for at the time he blessed he was not fit for the mitzvah, and it is not proper to say "and commanded us"; he did not bless at all—it is like invalid and he returns and blesses afterward. But regarding lulav—even though l'chatchila there is no [need] to bless beforehand, for while the lulav is in the vessel it is not reasonable to bless, as Tosafot wrote in Sukkah—nevertheless it is obvious b'dieved if he blessed while it rests in the vessel he fulfilled. And with this it is settled: for the Raavad, who holds regarding Birkat Eirusin we bless after betrothal—from concern lest he retract from consecrating; and why is this not counted in that baraita, to teach except immersion and Birkat Eirusin? According to the above it is fine: in any case b'dieved if he blessed before betrothal he fulfilled—therefore it cited only immersion, for here it is deficient even in doing it beforehand.`,
  '2#_': `(Seif 6) And afterward they brought him more. So is the Tur's language, and according to his reason: he concludes that even if while some of those on which he blessed are still before him they brought others before him, he must bless. The same applies if immediately after he blessed they brought before him to slaughter—he is obligated to bless on the others and obligated to cover first. But the Mechaber ruled in seif 7 that all the time he is occupied with shechita he need not bless on the others; and the Beit Yosef inferred thus from the Rosh's language, who wrote: one who blesses with intention to slaughter one chaya, and after it was slaughtered they brought him more, etc.—it appears specifically after it was slaughtered and not after he blessed; and see the Shach, seif kaf yod. If so, the Mechaber should have written the Rosh's language "after it was slaughtered"; and so at the end of the seif, before he blessed on the first covering—behold also after he blessed on all that he did not cover, he need not bless on the second covering—and requires further study.`,
});

// --- nekudot-hakesef (2) ---
patchFile('siman_019/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `(Hagahah, siman 19, seif 1) One who slaughters must bless beforehand, etc. In the Beit Yosef, and so too the Rambam, chapter 1 of Hilchot Shechitah, end of his words; and in many places he did not bring the source of this law—and it is a Gemara, first chapter of Pesachim daf 7: we say there, all mitzvot one blesses before doing them; and it brings there a baraita on shechita: one says "asher kidshanu bemitzvotav vetzivanu al hashechitah"; and so it is in the Yerushalmi, chapter HaRo'eh: the slaughterer [says] "Blessed are You... upon the shechita." Shechita—from when does one bless on it? Rabbi Yochanan said: before the shechita; Yossi ben Nehorai said: after he slaughters—lest the shechita become invalid; from now examine the signs—the presumption is that the intestines are kosher, end of his words; and we hold like Rabbi Yossi and like our Gemara, first chapter of Pesachim—until here the hagahah.`,
  '2#_': `(Seif kaf tet) One may say "those who say," etc.—this is not so, for the agreement of the poskim is like the first view; and so all the acharonim. In Siftei Kohen, seif kaf gimmel, one must pass the pen over "and further clear proof: they taught," until "and so generally where this reason does not apply he does not bless"; and so one must read: and so it appears from the words of R' Yonah, chapter "Three who ate" there—that the same applies to all other berachot that are before doing them: if he did not bless he does not bless afterward, see there; and also in Piskei Rekanati siman 72, etc.—thus it should read. And further I now found proof for my words from what Kol Bo wrote and the Beit Yosef brings in Orach Chaim siman 432: if he did not examine before he begins to examine, he blesses all the time he has not finished his examination—for every mitzvah that has duration, wherever he blessed before the end of the mitzvah, it is "before doing it," end of his words; and so Rabbeinu the Rambam there in the hagahah: specifically all the time he has not finished his examination he blesses, but not afterward; and so it appears from the words of the poskim regarding Birkat Eirusin, see there.`,
});

// --- kaf-hachayim (8) ---
patchFile('siman_019/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `(1) [Seif 1] One who slaughters must bless, etc.; and if he slaughtered and did not bless—it is kosher. So too the Rambam, chapter 1 of Hilchot Shechitah; and the Rosh and Mordekhai at the beginning of Chullin—not like the laws of Eldad HaDani, who wrote if he slaughtered and did not bless it is pigul; and also not like what the Mordekhai wrote in the chapter on kisuy hadam, who found Rabbenu Yitzchak bar Avraham in a responsum of the Geonim that one who slaughtered deliberately and did not bless is forbidden to eat from it, but for others it is permitted, and he is liable for lashes (Beit Yosef). And so the Shach, seif kaf alef, in the name of several poskim, that even if deliberate and he did not bless it is kosher even for himself, see there. And so in ShakhneHag in the Hagahah Tashbetz, part 3, chapter 248, section 2, Lechem, section 3, Kereti, section 1, Shemen Chafetz, section 1, Shulchan Gavoah, section 1. However, where the people are lax regarding the mitzvah of kisuy hadam—who do not cover as required, or who do not bless on covering or on shechita—one should penalize him and obligate him lashes; and also forbid him shechita (for the transgressor, but for others it is permitted) because of fence-making (Rashal, chapter on kisuy hadam, siman 11). And so Lechem there. Lechem Yehudah there. Shemen Chafetz there. And so the Shach below siman 28, seif kaf gimmel. Pri Chadash in this siman, section 1, Kometz, section 1, Zivchei Ra'anan, siman 18, in Temidim, section 3, Menachem Nachum, section 1, Zivchei Tzedek, section 1.`,
  '2#_': `(2) There. One who slaughters must bless, etc.; and likewise one who slaughters for others blesses (Zivchei Ra'anan there in additions, section 1; Menachem Nachum there). And so in Orach Chaim siman 432, section 27, regarding examination of chametz, in the name of several poskim, that if the homeowner is obligated on another to examine it, the other blesses after he blesses, see there. And so below, siman 265, regarding milah—that the circumciser blesses even though it is not his son, see there. And see below, section 7.`,
  '3#_': `(3) Ben Paku'a that spread out on the ground and requires shechita from doubt—he blesses on the shechita (Peri Chadash, section 1). But the Peri To'ar, section 1, wrote he should not bless, see there; and we already wrote on this above siman 13, section 20, see there.`,
  '4#_': `(4) There. One who slaughters must bless beforehand, etc.—for all mitzvot one blesses before doing them (Pesachim 7b).`,
  '5#_': `(5) There. One who slaughters must bless beforehand, etc.—meaning we are not concerned lest it become invalid in his hand, nor lest treifah be found—for we establish the presumption of kashrut, and the slaughterer does not desire nevelah (Peri To'ar, section 2; Zivchei Tzedek, section 2). And see below siman 28, section 110.`,
  '6#_': `(6) And if he forgot and slaughtered and did not bless before shechita—he does not bless after shechita (Shach, seif kaf gimmel; ShakhneHag in Hagahah Tashbetz, section 4; Peri To'ar, section 3; Kereti, section 3; Shemen Chafetz, section 1; Pri Chadash, section 2; Shulchan Gavoah, section 3; Orach Chaim, siman 4, section 2; Chokhmat Adam, general rule 5, section 1; Pithei Teshuvah, section 3, in the name of responsa Tiferet Tzvi siman 3; Zivchei Ra'anan in Temidim, section 4). And the reason: since he was fit to bless beforehand and pushed himself aside—for since it was pushed aside it was pushed aside (Zivchei Ra'anan there). And even within the time of speech after completing shechita he does not bless (Kereti there; Shemen Chafetz there; Orach Chaim there; Zivchei Ra'anan there; Zivchei Shalom, section 1; Zivchei Tzedek, section 2). And although there is an opinion that he blesses—they are not difficult, for one does not bless because he holds so. However, if possible, he should return after another behama or bird to slaughter and bless on it and intend to discharge this one too (Shemen Chafetz there; Lechem Yehudah there; Zivchei Ra'anan there; Zivchei Tzedek there).`,
  '7#_': `(7) There. "And commanded us upon the shechita." And they instituted to bless "ba'al" and not in the language of "to slaughter," because it is a mitzvah that can be fulfilled through another even if he is not the owner of the behama or bird; therefore they bless "ba'al," as the language "al" comes to say the Torah was not particular that the animal be slaughtered if he wishes to eat it and the slaughterer be whoever it may be (Levush). And if he blessed in the language "to slaughter" he fulfilled, as written in our words in Orach Chaim siman 432, section 7, see there.`,
  '8#_': `(8) There, hagahah. And if he slaughters something in which a defect may develop, etc.; and when it is found kosher he blesses, etc.; and even though we wrote above, section 6, that one does not bless after shechita—here it is different because he could not bless beforehand, it was not pushed aside (Shach, seif kaf dalet; Kereti, section 3; Shemen Chafetz, section 2; Pri Chadash, section 4; Chokhmat Adam, general rule 5, section 1; Zivchei Ra'anan in Temidim, section 7; Zivchei Tzedek, section 3).`,
});

// --- yad-avraham (1) ---
patchFile('siman_019/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 19, seif 1) One who slaughters must bless. So it is in Seder Parashiyot Aseret, and in many places, end of chapter 6 of Berachot.`,
});

// --- yad-ephraim (1) ---
patchFile('siman_019/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `Provided that he be close to the shechita. BeHag; and see in Sha'agat Aryeh who attacked the Shach; and likewise the Peri Chadash attacked; and see in Taz that there is no decision in this dispute; and see in Tiferet Tzvi siman 3, who extended to settle the Shach's words, see there.`,
});
